<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserWelcomeAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWelcomeAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserWelcomeAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getWelcomeAt returns null on a freshly created holder.
     */
    public function testWelcomeAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWelcomeAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isWelcomeAtAssigned());
        $this->assertNull($holder->getWelcomeAt());
    }
}
class ImplWithUserWelcomeAtAttributeHolderUnitTest
{
    use UserWelcomeAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedWelcomeAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultWelcomeAt();
    }
}
